xwikidoc.content:
{{velocity}}

#set ($parameterFields ='<p>You can tweak how metadata sets will be migrated. If unsure, leave the default values.</p><div class="xform"><dl>
  <dt>
    <label for="setreferencetemplate">Metadata set reference</label>
    <span class="xHint">Import metadata sets at this location in the wiki. ${spaceKey} will be replaced with the key of the space in which the metadata sets were stored in Confluence and ${setName} will be replaced with the name of the metadata sets (without the "metadataset." prefix)</span>
  </dt>
  <dd>
    <input type="text" name="setreferencetemplate" id="setreferencetemplate" value="MetadataPro.Sets.${spaceKey}_${setName}" />
  </dd>
  <dt>
    <label for="settitletemplate">Metadata set title</label>
    <span class="xHint">Use this user-friendly title. The same replacements as for the previous field will be done.</span>
  </dt>
  <dd>
    <input type="text" name="settitletemplate" id="settitletemplate" value="${setName}" />
  </dd>
</dl></div>')

#if ($doc.isNew())
  #if ($objecttool.isNull($xwiki.getDocument("MetadataPro.MetadataForConfluenceMigrator.Code.PackagesStore").getAttachment($request.package)))

    {{error}}
    Package $services.rendering.escape($request.package, $doc.getSyntax) does not exist.
    {{/error}}

  #else

    You are about to import the {{code language=none}}$request.package{{/code}} package.

    When you are ready, click {{html}}$services.localization.render("saveandview"){{/html}}.

    {{html}}
    <input type="hidden" classname="MetadataPro.MetadataForConfluenceMigrator.Code.MigrationClass" />
    <input type="hidden" name="MetadataPro.MetadataForConfluenceMigrator.Code.MigrationClass_0_package" value="$escapetool.xml($request.package)" />
    <input type="hidden" name="MetadataPro.MetadataForConfluenceMigrator.Code.MigrationClass_0_executed" value="0" />
    <input type="hidden" name="addedObjects" value="MetadataPro.MetadataForConfluenceMigrator.Code.MigrationClass_0" />
    <input type="hidden" name="startmigration" value="true" />
    $parameterFields
    {{/html}}

  #end
#else
  #set ($obj = $doc.getObject("MetadataPro.MetadataForConfluenceMigrator.Code.MigrationClass"))
  #set ($executed = $obj.getValue("executed"))
  #set ($storeDoc = $xwiki.getDocument("MetadataPro.MetadataForConfluenceMigrator.Code.PackagesStore"))
  #set ($packageName = $obj.getValue("package"))
  #set ($stats = $jsontool.fromString($doc.getAttachment("stats.json").getContentAsString()))

  |=$services.localization.render("metadatapro.metadataforconfluencemigration.package")|[[$services.rendering.escape($services.rendering.escape($packageName, 'xwiki/2.1'), 'xwiki/2.1')>>path:$storeDoc.getAttachmentURL($packageName)]]
  |=$services.localization.render("metadatapro.metadataforconfluencemigration.executed")|#if ($executed == 0)$services.localization.render("metadatapro.no")#{else}$services.localization.render("metadatapro.yes")#end|
  |=$services.localization.render("metadatapro.metadataforconfluencemigration.space")|$stringtool.join($obj.getValue('spaces'), ", ")
  #if ($objecttool.isNotNull($stats))
  #foreach ($e in $stats.entrySet())
  |=$services.localization.render("metadatapro.metadataforconfluencemigration.stat.$e.key")|$e.value
  #end
  #end

  #if ("$executed" == "0")

    #if (!$request.startmigration)

      {{html}}
      <form method="post">
        $parameterFields
        <p>
          <button class="btn btn-primary" name="startmigration" value="true">$services.localization.render("metadatapro.actions.startmigration")</button>
        </p>
      </form>
      {{/html}}

    #end
  #end
#end
{{/velocity}}

{{job id="{{velocity}}$doc.fullName{{/velocity}}" start="{{velocity}}$!request.startmigration{{/velocity}}" grouppath="metadatapro/metadataforconfluencemigration"}}
{{groovy}}
  def log = services.logging.getLogger(doc.fullName);
  try {
    services.logging.setLevel(doc.fullName, org.xwiki.logging.LogLevel.INFO);
    services.get("metadatapro.metadataforconfluencemigration").run(doc, request.setreferencetemplate, request.settitletemplate);
  } catch (e) {
    log.error("Something seriously wrong happened during the migration", e);
  }
{{/groovy}}
{{/job}}

{{velocity}}

#if ($!request.startmigration)

{{info}}
$services.localization.render('metadatapro.metadataforconfluencemigration.refreshinvite')
{{/info}}

#end
{{/velocity}}
